/* Fill a complete store record: defaults for everything the preset does not mention (remembered
 * params of inactive effects), then the preset. Apply with engine_apply_config(e, &d->cfg). */
static inline void factory_preset_fill(const factory_preset_t *p, store_data_t *d)
{
	store_data_default(d);
	for (int s = 0; s < ENGINE_SLOTS; s++) {
		d->cfg.fx_id[s] = p->fx_id[s];
		d->cfg.bypass[s] = p->bypass[s];
		d->cfg.wet[s] = p->wet[s];
		d->cfg.order[s] = p->order[s];
		const fx_desc *fd = fx_get(p->fx_id[s]);
		for (int i = 0; fd && i < fd->nparams; i++) d->cfg.params[s][p->fx_id[s]][i] = p->params[s][i];
	}
	d->cfg.global_bypass = p->global_bypass;
	d->cfg.in_gain_db = p->in_gain_db;
	d->cfg.master = p->master;
	d->bpm = p->bpm;
}

